// ── Pont de langue (chantier RTL/arabe, 2026-09-25) ─────────────────────────
// La page Réglages ▸ Thème ▸ Langue traduit à la demande (moteur LLM du plugin
// thème, caché dans localStorage `kybernos.i18n.<lang>`) et expose
// `window.__KB_I18N_ACTIVE__`. La locale hôte, elle, ne connaît que fr/en :
// pour qu'une langue traduite (ar, es…) peigne l'interface, `kbt` consulte
// d'abord la langue active du thème, puis son dict — mis en cache ici (UNE
// lecture localStorage par langue et par page, pas par appel : `kbt` tourne
// des centaines de fois par rendu). Une langue absente du dict retombe sur
// l'anglais, comme avant — jamais de trou.
const KB_LANG_FALLBACK = 'en'
const KB_RTL_BASES = ['ar', 'he', 'fa', 'ur']
const kbLangActive = () => {
  try {
    const a = (typeof window !== 'undefined') ? window.__KB_I18N_ACTIVE__ : null
    if (a !== null && a !== undefined && a.lang !== null && a.lang !== undefined && String(a.lang) !== '') {
      const act = String(a.lang)
      if (act !== 'kybernos') return act
      // (01/10) « kybernos » posé par le thème est le DÉFAUT, pas un choix :
      // quand le shell parle anglais et que l'utilisateur n'a rien choisi dans
      // la page Thème (aucune clé kybernos.theme.lang), servir la variante en —
      // des onglets anglais sous un shell anglais. Un choix explicite
      // « Langue source » écrit la clé et reprend la main.
      try {
        if (localStorage.getItem('kybernos.theme.lang') === null && kbLocaleRead() === 'en') return 'en'
      } catch (e2) { /* storage indisponible : défaut */ }
      return act
    }
  } catch (e) { /* window indisponible (harnais de test) */ }
  try { const l = localStorage.getItem('kybernos.theme.lang'); if (l !== null && l !== '') return String(l) } catch (e) { /* localStorage indisponible */ }
  return null
}
let kbI18nCache = { lang: null, dict: null }
const kbI18nDict = (lang) => {
  if (lang === null || lang === undefined) return null
  if (lang === 'kybernos' || lang === KB_LANG_FALLBACK) return null
  if (kbI18nCache.lang === lang) return kbI18nCache.dict
  let dict = null
  try {
    const raw = localStorage.getItem('kybernos.i18n.' + lang)
    if (raw !== null) {
      const parsed = JSON.parse(raw)
      if (parsed !== null && typeof parsed === 'object') dict = parsed
    }
  } catch (e) { /* dict absent ou corrompu */ }
  kbI18nCache = { lang, dict }
  return dict
}

// ── Favoris partagés (Projets, Kybers, Automations) ──────────────────────────
// Une seule clé localStorage pour les trois panneaux : chaque scope porte ses
// ids marqués à true. Lecture défensive (clé absente, JSON corrompu ou
// stockage indisponible = objet vide neuf), écriture silencieuse (mode privé),
// bascule lire-modifier-écrire qui rend la map à jour pour l’état React.
const KB_FAV_KEY = 'kybernos.favorites.v1'
const KB_FAV_SCOPES = ['workspaces', 'kybers', 'automations']
const kbFavRead = () => {
  const out = { workspaces: {}, kybers: {}, automations: {} }
  try {
    const raw = window.localStorage.getItem(KB_FAV_KEY)
    if (raw === null || raw === '') return out
    const parsed = JSON.parse(raw)
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed) === true) return out
    for (const sc of KB_FAV_SCOPES) {
      if (parsed[sc] === null || typeof parsed[sc] !== 'object' || Array.isArray(parsed[sc]) === true) continue
      for (const id of Object.keys(parsed[sc])) if (parsed[sc][id] === true) out[sc][id] = true
    }
  } catch (e) { /* window/localStorage indisponible ou JSON corrompu : objet vide */ }
  return out
}
const kbFavWrite = (map) => {
  try { window.localStorage.setItem(KB_FAV_KEY, JSON.stringify(map)) } catch (e) { /* stockage indisponible */ }
}
const kbFavToggle = (scope, id) => {
  const map = kbFavRead()
  const sc = (map[scope] !== null && map[scope] !== undefined && typeof map[scope] === 'object') ? map[scope] : {}
  if (sc[id] === true) delete sc[id]
  else sc[id] = true
  map[scope] = sc
  kbFavWrite(map)
  return map
}
const kbFavOn = (map, scope, id) => (map !== null && map !== undefined && map[scope] !== null && map[scope] !== undefined && map[scope][id] === true)

// Filet RTL au chargement du module (le plugin thème refait la même pose à son
// activation — l'ordre des deux bundles ne doit pas compter).
try {
  const kbLangBoot = kbLangActive()
  if (kbLangBoot !== null) {
    const base = String(kbLangBoot).split(/[-_]/)[0]
    document.documentElement.setAttribute('dir', KB_RTL_BASES.indexOf(base) >= 0 ? 'rtl' : 'ltr')
    document.documentElement.setAttribute('lang', kbLangBoot === 'kybernos' ? 'fr' : kbLangBoot)
  }
} catch (e) { /* document indisponible */ }

// Langue effective de l'interface Kybernos : UNE règle pour kbt et pour les autres
// plugins de Réglages (thème, langue, commandes, maintenance) via
// `window.__KB_LANG_RESOLVE__`. « kybernos » (défaut) + aucune clé
// kybernos.theme.lang + shell en anglais => 'en'.
const kbLangResolve = () => {
  let lang = kbLangActive()
  if (lang === null) {
    try { lang = String(kbLocaleRead()) } catch (e) { lang = KB_LANG_FALLBACK }
    // Politique de langue (chasse Settings 27/09, P2-3/P2-5 ; étendue 01/10) :
    // sans choix Kybernos explicite, on suit le shell quand sa langue est
    // réellement servie par nos tables — l'anglais (KB_T est bilingue
    // complet kybernos/en) et les bases RTL (ar/he/fa/ur) ; toute autre
    // langue retombe sur le français Kybernos.
    const kbBase = String(lang).split(/[-_]/)[0]
    if (kbBase !== 'en' && KB_RTL_BASES.indexOf(kbBase) < 0) lang = 'kybernos'
  }
  return lang
}
try { if (typeof window !== 'undefined') window.__KB_LANG_RESOLVE__ = kbLangResolve } catch (e) { /* hors navigateur */ }
const kbt = (key) => {
  const lang = kbLangResolve()
  const entry = KB_T[key]
  if (entry === null || entry === undefined) {
    // Clé hors KB_T : un dict traduit généré depuis un source plus riche peut
    // quand même la porter — on la rend, sinon inchangée.
    const d = kbI18nDict(lang)
    if (d !== null && d[key] !== undefined) return String(d[key])
    return key
  }
  if (entry[lang] !== undefined) return entry[lang]
  const d = kbI18nDict(lang)
  if (d !== null && d[key] !== undefined) return String(d[key])
  return entry.en !== undefined ? entry.en : key
}

