/**
 * Fusion commune au projet et a la fiche d'equipe : ce que les roles DECLARENT
 * (champ tools: du kyber.yml), puis ce que le COMPTE a connecte en plus, sans
 * doublon de toolkit. `actif` faux => aucun appel reseau (onglet ferme).
 */
/** Outils reclames dans un kyber.yml : `tools:` / `connectors:` (listes en ligne). */
const kbYmlTools = (texte) => {
  const out = []
  let role = ''
  for (const ligne of String(texte === null || texte === undefined ? '' : texte).split('\n')) {
    const rid = /^\s*-\s*id:\s*([^\s#]+)/.exec(ligne)
    if (rid !== null) { role = rid[1]; continue }
    const lst = /^(\s*)(?:tools|connectors):\s*\[([^\]]*)\]/.exec(ligne)
    if (lst === null) continue
    for (const brut of lst[2].split(',')) {
      const nom = brut.trim().replace(/^['"]/, '').replace(/['"]$/, '')
      // Sans indentation, le besoin est celui de l'EQUIPE, pas d'un role.
      if (nom.length > 0) out.push({ nom: nom, role: lst[1].length === 0 ? '' : role })
    }
  }
  return out
}

const kbConnMerge = (slugs, actif) => {
  if (actif !== true) return null
  const declaration = kbComposioConnections(slugs)
  const balayage = kbConnScan()
  // Des outils declares : tant que leur etat est en lecture, on l'annonce — le
  // balayage ne doit pas parler a leur place.
  if (declaration === null && slugs.length > 0) return null
  if (declaration === null) return balayage
  if (balayage === null) return declaration
  const vus = {}
  const out = []
  for (const c of (Array.isArray(declaration.connections) === true ? declaration.connections : [])) { vus[c.toolkit] = true; out.push(c) }
  for (const c of (Array.isArray(balayage.connections) === true ? balayage.connections : [])) if (vus[c.toolkit] !== true) out.push(c)
  // Si la route des outils declares a echoue, c'est le balayage qui porte la
  // verite (et ses drapeaux) : on ne garde pas un « route absente » faux.
  const base = (declaration.missing === true || declaration.offline === true) ? balayage : declaration
  return Object.assign({}, base, { connections: out, scan: balayage.scan === true || declaration.scan === true })
}

/** Lignes « connexions » communes : une ligne par compte, puis les declares seuls. */
const kbConnRowsOf = (connsReal, declaredTools, hit) => {
  const realBySlug = {}
  const connRows = []
  if (connsReal !== null && Array.isArray(connsReal.connections) === true) {
    for (const c of connsReal.connections) {
      const slug = String(c.toolkit === null || c.toolkit === undefined ? '' : c.toolkit).toLowerCase()
      const accounts = Array.isArray(c.accounts) === true ? c.accounts : []
      realBySlug[slug] = true
      if (accounts.length === 0) {
        if (hit(slug)) connRows.push({ key: 'real/' + slug, name: slug, meta: kbf('Composio · aucun compte connecté'), state: String(c.status === null || c.status === undefined ? 'unknown' : c.status).toUpperCase(), real: true, slug: slug, account: null })
        continue
      }
      for (const a of accounts) {
        const label = (typeof a.alias === 'string' && a.alias.length > 0) ? a.alias : String(a.id)
        if (hit(slug + ' ' + label) === false) continue
        connRows.push({
          key: 'real/' + slug + '/' + String(a.id), name: slug, real: true, slug: slug, account: String(a.id),
          meta: 'Composio · ' + label + (typeof a.accountType === 'string' && a.accountType.length > 0 ? ' · ' + a.accountType : '') + (a.isDefault === true ? ' · défaut' : ''),
          state: String(a.status === null || a.status === undefined ? c.status : a.status).toUpperCase(),
        })
      }
    }
  }
  for (const d of declaredTools) {
    if (realBySlug[d.slug] === true) continue
    if (hit(d.name + ' ' + d.kyber) === false) continue
    connRows.push({
      key: 'decl/' + d.key, name: d.name, meta: d.kyber + ' · ' + d.role + kbf(' · déclaré, non connecté'),
      state: connsReal !== null && connsReal.configured === false ? kbf('SANS CLÉ') : kbf('NON CONNECTÉ'),
      real: false, slug: d.slug, account: null,
    })
  }
  return { connRows: connRows, realBySlug: realBySlug }
}

/**
 * Action commune : le PREMIER clic arme seulement (aucun appel, aucune cle
 * requise) ; le second execute — retrait d'un compte, ou lien d'autorisation.
 */
const kbConnActionOf = async (c, arm, setArm, setAction) => {
  if (c === null || typeof c.slug !== 'string' || c.slug.length === 0) return
  const desactiver = (c.real === true && c.account !== null && c.account !== undefined && c.account !== '')
  if (desactiver === true && arm !== c.key) { setArm(c.key); setAction(null); return }
  setArm(null)
  if (kbConnKey().indexOf('ck_') !== 0) { setAction({ key: c.key, etat: 'err', message: kbt('kbui.conn.nokey'), lien: null }); return }
  setAction({ key: c.key, etat: 'busy', message: kbt('kbui.conn.doing'), lien: null })
  try {
    const res = await kbConnMcp('COMPOSIO_MANAGE_CONNECTIONS', { toolkits: [desactiver === true ? { name: c.slug, action: 'remove', account_id: c.account } : { name: c.slug, action: 'add' }] })
    const lien = desactiver === true ? null : kbConnLien(res)
    if (lien !== null) { try { window.open(lien, '_blank', 'noopener') } catch (e) { /* ouverture refusee : le lien reste affiche */ } }
    kbConnForget()
    setAction({ key: c.key, etat: 'ok', message: desactiver === true ? kbt('kbui.conn.okoff') : kbt('kbui.conn.okon'), lien: lien })
  } catch (e) {
    setAction({ key: c.key, etat: 'err', message: kbt('kbui.conn.err') + String((e !== null && e !== undefined && e.message !== undefined) ? e.message : e), lien: null })
  }
}


