        const sel = (rep !== null && rep !== undefined && Array.isArray(rep.selected) && rep.selected.length > 0) ? rep.selected.join(', ') : ((rep !== null && rep !== undefined && typeof rep.custom === 'string' && rep.custom !== '') ? rep.custom : null)
