      if (cible === null && slug === '' && items.length > 0) cible = items[0]
      const nouveau = (cible === null)
      const base = (nouveau === true) ? kbwNorm({ id: 'w' + String(Date.now()), slug: (slug !== '' ? slug : 'widget'), label: (a.nom !== undefined ? a.nom : (a.label !== undefined ? a.label : (slug !== '' ? slug : 'Widget'))), enabled: true }) : Object.assign({}, cible)
