      globe: 'M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18zM3 12h18M12 3c2.5 2.7 3.8 5.7 3.8 9s-1.3 6.3-3.8 9c-2.5-2.7-3.8-5.7-3.8-9s1.3-6.3 3.8-9z',
      headphones: 'M4 17v-5a8 8 0 0 1 16 0v5M4 15h3v5H4zM17 15h3v5h-3z',
      bulb: 'M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.6.5 1 1.2 1 2.1h5c0-.9.4-1.6 1-2.1A6 6 0 0 0 12 3z',
      braces: 'M8 4c-2 0-2 1-2 3s0 3-2 5c2 2 2 3 2 5s0 3 2 3M16 4c2 0 2 1 2 3s0 3 2 5c-2 2-2 3-2 5s0 3-2 3',
      thermo: 'M10 14V5a2 2 0 0 1 4 0v9a4 4 0 1 1-4 0z',
      chat: 'M4 5h16v11H9l-5 4z',
      layers: 'M12 3l9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5',
