        id: String(m.id), provider: String((m !== null && m !== undefined && m.provider !== null && m.provider !== undefined) ? m.provider : '—'), type: 'Image',
        in: ['text', 'vision'], out: ['image'], caps: [],
        price: null, priceLabel: (price !== null ? ('$' + price.toFixed(2) + ' / image') : 'price unknown'),
        short: (price !== null ? ('≈ $' + price.toFixed(2) + ' / image') : 'no price data'),
        latency: null, intel: 1,
        health: (probe === 'ok' ? 'healthy' : (probe === 'fail' ? 'down' : 'none')),
        aa: null, bl: null,
        foot: (price !== null ? ('$' + price.toFixed(2) + ' per image · probe ' + (probe || 'none')) : ('probe ' + (probe || 'none'))),
        info: 'Probe ' + (probe || 'none') + ' · ' + String((m !== null && m !== undefined && typeof m.attempts === 'number') ? m.attempts : 0) + ' attempts'
