    // Stocké dans un ref mutable pour éviter les re-renders inutiles.
    const kbMiniAppState = { current: null, mode: 'inline', picks: {}, checked: false, round: 1, subs: [] }
    const kbMiniAppNotify = () => { kbMiniAppState.subs.forEach((fn) => { try { fn() } catch (e) {} }) }
    const kbMiniAppOpen = (fileName, text, mode, chemin) => {
      kbMiniAppState.current = { fileName: fileName, text: text, path: (typeof chemin === 'string' && chemin.length > 0) ? chemin : null }
      kbMiniAppState.picks = {}; kbMiniAppState.checked = false; kbMiniAppState.round = 1
      if (mode) kbMiniAppState.mode = mode
      kbMiniAppNotify()
    }
    const kbMiniAppClose = () => { kbMiniAppState.current = null; kbMiniAppState.mode = 'inline'; kbMiniAppNotify() }
    const kbMiniAppSetMode = (mode) => { kbMiniAppState.mode = mode; kbMiniAppNotify() }

    // Charger un .miniapp.json via fetch direct.
    // `chemin` : le chemin RÉEL de la carte (attribut `title` de la carte
