          const zoomBy = (f) => setS((s) => {
            const k = Math.max(0.35, Math.min(2.5, s.view.k * f))
            const g = k / s.view.k
            return Object.assign({}, s, { view: { x: 775 - g * (775 - s.view.x), y: 145 - g * (145 - s.view.y), k: k } })
          })
          const onCanvasDown = (e) => {
            e.currentTarget.setPointerCapture(e.pointerId)
            panRef.current = { sx: e.clientX, sy: e.clientY, ox: S.view.x, oy: S.view.y }
            set({ panning: 1 })
          }
          const onCanvasMove = (e) => {
            const p = panRef.current
            if (!p) return
            setS((s) => Object.assign({}, s, { view: Object.assign({}, s.view, { x: p.ox + (e.clientX - p.sx), y: p.oy + (e.clientY - p.sy) }) }))
          }
