          const onNodeDown = (e, n) => {
            e.stopPropagation()
            e.currentTarget.setPointerCapture(e.pointerId)
            const o = ((S.npos || {})[S.run + ':' + n.id]) || { x: 0, y: 0 }
            nodeDrag.current = { id: n.id, sx: e.clientX, sy: e.clientY, moved: 0, ox: o.x, oy: o.y }
          }
          const onNodeMove = (e) => {
            const d = nodeDrag.current
            if (!d) return
            const dx = (e.clientX - d.sx) / S.view.k, dy = (e.clientY - d.sy) / S.view.k
            d.moved = Math.max(d.moved, Math.abs(e.clientX - d.sx) + Math.abs(e.clientY - d.sy))
            const key = S.run + ':' + d.id
            setS((s) => Object.assign({}, s, { npos: Object.assign({}, s.npos, { [key]: { x: d.ox + dx, y: d.oy + dy } }) }))
          }
